"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

function GraphCorners() {
  return (
    <>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute top-0 left-0 z-10 block -translate-x-1/2 -translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        +
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute top-0 right-0 z-10 block translate-x-1/2 -translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        +
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute bottom-0 left-0 z-10 block -translate-x-1/2 translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        +
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute right-0 bottom-0 z-10 block translate-x-1/2 translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        +
      </span>
    </>
  )
}

function GraphTitle({
  className,
  children,
  ...props
}: React.ComponentProps<"figcaption">) {
  return (
    <figcaption
      className={cn(
        "absolute top-0 left-1/2 z-10 -translate-x-1/2 -translate-y-1/2 bg-background px-2.5 tracking-wide whitespace-nowrap text-graph-accent uppercase",
        className
      )}
      {...props}
    >
      [ {children} ]
    </figcaption>
  )
}

function GraphBody({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div className={cn("px-5 py-7 sm:px-8 sm:py-8", className)} {...props} />
  )
}

function GraphRule({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      className={cn("graph-rule w-full", className)}
      {...props}
    />
  )
}

function Graph({
  title,
  className,
  children,
  ...props
}: React.ComponentProps<"figure"> & {
  title?: string
}) {
  const captionId = React.useId()

  return (
    <figure
      aria-labelledby={title ? captionId : undefined}
      className={cn(
        "relative min-w-0 graph-frame font-mono text-sm text-foreground",
        className
      )}
      {...props}
    >
      {title ? <GraphTitle id={captionId}>{title}</GraphTitle> : null}
      <GraphCorners />
      {children}
    </figure>
  )
}

export { Graph, GraphBody, GraphCorners, GraphRule, GraphTitle }

import type { Transition, Variants } from "motion/react"

export const easeOutCubic = [0.215, 0.61, 0.355, 1] as const

export const DIM_OPACITY = 0.4

export function graphTransition(
  reduce: boolean | null,
  extras?: Transition
): Transition {
  if (reduce) {
    return { duration: 0 }
  }

  return {
    duration: 0.22,
    ease: easeOutCubic,
    ...extras,
  }
}

export function fadeUp(reduce: boolean | null): Variants {
  if (reduce) {
    return {
      hidden: { opacity: 1, transform: "translateY(0px)" },
      show: { opacity: 1, transform: "translateY(0px)" },
    }
  }

  return {
    hidden: { opacity: 0, transform: "translateY(8px)" },
    show: {
      opacity: 1,
      transform: "translateY(0px)",
      transition: graphTransition(false),
    },
  }
}

export function staggerList(reduce: boolean | null, stagger = 0.04): Variants {
  return {
    hidden: {},
    show: {
      transition: reduce ? { duration: 0 } : { staggerChildren: stagger },
    },
  }
}

export function fillDelay(reduce: boolean | null, index: number, step = 0.03) {
  if (reduce) {
    return 0
  }

  return Math.min(index * step, 0.28)
}

export function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

"use client"

import { motion, useReducedMotion } from "motion/react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  DIM_OPACITY,
  fadeUp,
  staggerList,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

const DEFAULT_GLYPHS = ["█", "▓", "▒", "░", "#", "=", "+", "-"]

type StackSegment = {
  label: string
  value: number
}

type StackRow = {
  label: string
  segments: StackSegment[]
}

type GraphStackProps = {
  title: string
  rows: StackRow[]
  accent?: string
  ticks?: number
  glyphs?: string[]
  className?: string
}

type Painted = {
  label: string
  glyph: string
  count: number
  accent: boolean
}

function paintRow(
  segments: StackSegment[],
  ticks: number,
  glyphs: string[],
  accentLabel?: string
): Painted[] {
  const total = segments.reduce((sum, segment) => sum + segment.value, 0) || 1
  let left = ticks

  return segments.map((segment, index) => {
    const raw = Math.round((segment.value / total) * ticks)
    const count =
      index === segments.length - 1
        ? Math.max(0, left)
        : Math.min(Math.max(0, raw), left)
    left -= count
    const highlighted = accentLabel
      ? segment.label === accentLabel
      : index === 0

    return {
      label: segment.label,
      glyph: glyphs[index % glyphs.length] ?? "█",
      count,
      accent: highlighted,
    }
  })
}

function GraphStack({
  title,
  rows,
  accent,
  ticks = 24,
  glyphs = DEFAULT_GLYPHS,
  className,
}: GraphStackProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.05)
  const legend: string[] = []

  for (const row of rows) {
    for (const segment of row.segments) {
      if (!legend.includes(segment.label)) {
        legend.push(segment.label)
      }
    }
  }

  return (
    <Graph title={title} className={className}>
      <GraphBody className="flex flex-col gap-6 overflow-x-auto">
        <motion.ul
          role="list"
          className="flex flex-col gap-3"
          initial={reduce ? false : "hidden"}
          variants={list}
          viewport={{ once: true, amount: 0.4 }}
          whileInView="show"
        >
          {rows.map((row) => {
            const painted = paintRow(row.segments, ticks, glyphs, accent)

            return (
              <motion.li
                key={row.label}
                className="grid grid-cols-[7rem_minmax(0,1fr)] items-center gap-x-4"
                variants={item}
              >
                <span className="truncate text-foreground">{row.label}</span>
                <span aria-hidden="true" className="flex select-none">
                  {painted.map((piece) => (
                    <span
                      className={cn(
                        "flex",
                        piece.accent ? "text-graph-accent" : "text-foreground"
                      )}
                      key={piece.label}
                      style={
                        piece.accent ? undefined : { opacity: DIM_OPACITY }
                      }
                    >
                      {Array.from({ length: piece.count }, (_, index) => (
                        <span className="w-[1ch] text-center" key={index}>
                          {piece.glyph}
                        </span>
                      ))}
                    </span>
                  ))}
                </span>
                <span className="sr-only">
                  {row.label}:{" "}
                  {row.segments
                    .map((segment) => `${segment.label} ${segment.value}`)
                    .join(", ")}
                </span>
              </motion.li>
            )
          })}
        </motion.ul>
        <ul className="flex flex-wrap gap-x-4 gap-y-1" role="list">
          {legend.map((label, index) => {
            const glyph = glyphs[index % glyphs.length] ?? "█"
            const highlighted = accent ? label === accent : index === 0

            return (
              <li
                className="flex items-center gap-2"
                key={label}
                style={highlighted ? undefined : { opacity: DIM_OPACITY }}
              >
                <span
                  aria-hidden="true"
                  className={cn(
                    highlighted ? "text-graph-accent" : "text-foreground"
                  )}
                >
                  {glyph}
                </span>
                <span
                  className={
                    highlighted ? "text-foreground" : "text-graph-muted"
                  }
                >
                  {label}
                </span>
              </li>
            )
          })}
        </ul>
      </GraphBody>
    </Graph>
  )
}

export { GraphStack }
export type { GraphStackProps, StackRow, StackSegment }
